SELECT s.schedule_id, s.namespace_id, s.report_id, s.version_no, s.interval_seconds, s.first_run_at, s.next_due_at, s.enabled, s.revision, s.last_run_id, s.created_at, s.created_by, s.updated_at, s.updated_by FROM component_warmup_schedules s WHERE ($ScheduleId = '' OR s.schedule_id = $ScheduleId) AND ($ReportId = '' OR s.report_id = $ReportId) AND ($VersionNo = 0 OR s.version_no = $VersionNo) AND ($DueBefore IS NULL OR (s.enabled = TRUE AND s.next_due_at <= $DueBefore)) AND ($AfterDue IS NULL OR s.next_due_at > $AfterDue OR (s.next_due_at = $AfterDue AND s.schedule_id > $AfterId)) ORDER BY s.next_due_at,s.schedule_id LIMIT $PageLimit
